from __future__ import annotations

"""Render the approved dual Word reports from one canonical twelve-item run.

The accepted Clinic payload remains the wording/layout baseline.  This adapter
only rebinds its image slots to artifacts produced by the same ``run.py``
invocation; it never reruns or re-renders an algorithm image.
"""

import copy
from datetime import date
import hashlib
import json
import os
import shutil
import tempfile
from pathlib import Path
from typing import Any

from src.capture_profile import CaptureProfile

from .controlled_evidence import (
    ControlledEvidencePaths,
    RuntimeItems,
    bind_controlled_evidence,
    materialize_controlled_evidence,
)
from .integration import DEFAULT_TEMPLATE
from .report import render_doctor_docx, render_user_docx
from .controlled_report_metrics import apply_vascular_metric_layout


PROJECT_ROOT = Path(__file__).resolve().parents[2]
CAPTURE_ALIASES = ("clinic28-25", "clinic28-09", "clinic28-23")
DEFAULT_BASELINE_ROOT = (
    PROJECT_ROOT.parent / "00_runtime_assets/frozen_formal_word_baseline"
)


def refresh_report_dates(payload: dict[str, Any], value: date) -> None:
    """Use the current delivery date instead of the frozen fixture date."""
    current = value.isoformat()
    payload.setdefault("报告信息", {})["报告日期"] = current
    payload.setdefault("受检者信息", {})["采集日期"] = current


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _baseline_root() -> Path:
    configured = os.environ.get("AISIA_FORMAL_BASELINE_ROOT")
    root = Path(configured).expanduser() if configured else DEFAULT_BASELINE_ROOT
    root = root.resolve()
    if not root.is_dir():
        raise FileNotFoundError(
            "定稿正式报告基线不存在；可用 AISIA_FORMAL_BASELINE_ROOT 指定: "
            f"{root}"
        )
    return root


def _baseline_json(root: Path, alias: str) -> Path:
    path = (
        root
        / alias
        / "reports/formal_evidence"
        / f"AISIA_{alias}_正式结构化数据.json"
    )
    if not path.is_file():
        raise FileNotFoundError(path)
    return path


def _capture_alias(result_root: Path, index: dict[str, Any], baseline_root: Path) -> str:
    for alias in CAPTURE_ALIASES:
        if alias in result_root.name:
            return alias
    source = result_root / str(index["输入图像"])
    source_sha = _sha256(source)
    for alias in CAPTURE_ALIASES:
        payload = json.loads(_baseline_json(baseline_root, alias).read_text(encoding="utf-8"))
        if str((payload.get("标准采集图像") or {}).get("sha256")) == source_sha:
            return alias
    raise ValueError(f"无法把固定RGB样本映射到Clinic-Fast3别名: {result_root.name}")


def _resolve_artifact(result_root: Path, relative: str) -> Path:
    path = (result_root / relative).resolve(strict=True)
    if not path.is_relative_to(result_root.resolve()) or path.is_symlink():
        raise ValueError(f"十二项产物越界: {relative}")
    return path


def _stage(path: Path, report_root: Path, module_id: str) -> Path:
    target = report_root / "evidence" / module_id / f"{_sha256(path)[:12]}_{path.name}"
    target.parent.mkdir(parents=True, exist_ok=True)
    if not target.is_file() or _sha256(target) != _sha256(path):
        shutil.copy2(path, target)
    return target


def _image_map(result_root: Path, index: dict[str, Any], report_root: Path) -> dict[str, Path]:
    items = index["十二项结果"]

    def main(item_id: str, module_id: str) -> Path:
        return _stage(
            _resolve_artifact(result_root, items[item_id]["主结果图"]),
            report_root,
            module_id,
        )

    def extra(item_id: str, position: int, module_id: str) -> Path:
        values = items[item_id].get("附加结果图") or []
        if position >= len(values):
            raise ValueError(f"{item_id} 缺少第 {position + 1} 张正式附加图")
        return _stage(
            _resolve_artifact(result_root, values[position]),
            report_root,
            module_id,
        )

    return {
        "01": main("pores", "01"),
        "02_oil": main("surface_gloss", "02"),
        "02_porphyrin": main("porphyrin", "02"),
        "03_visible": main("spots", "03"),
        "03_uv": main("uv_spots", "03"),
        "03_brown": main("brown", "03"),
        "04": main("redness", "04"),
        "05": main("vascular", "05"),
        "06": main("acne", "06"),
        "07": main("wrinkle", "07"),
        "08": extra("wrinkle", 0, "08"),
        "09": extra("wrinkle", 1, "09"),
        "10": main("texture", "10"),
        "11": main("contour_firmness", "11"),
    }


def _set_group_image(group: dict[str, Any], path: Path | None, caption: str) -> None:
    group["images"] = [] if path is None else [{"path": str(path), "caption": caption}]


def _bind_images(payload: dict[str, Any], images: dict[str, Path], source: Path) -> None:
    payload["标准采集图像"] = {
        "path": str(source),
        "caption": "标准白光正面图",
        "sha256": _sha256(source),
        "size_bytes": source.stat().st_size,
    }
    modules = {str(row["模块编号"]): row for row in payload["检测模块"]}
    result_images = {
        "01": [images["01"]],
        "02": [images["02_oil"], images["02_porphyrin"]],
        "03": [images["03_brown"], images["03_visible"], images["03_uv"]],
        "04": [images["04"]],
        "05": [images["05"]],
        "06": [images["06"]],
        "07": [images["07"]],
        "08": [images["08"]],
        "09": [images["09"]],
        "10": [images["10"]],
        "11": [images["11"]],
    }
    for module_id, paths in result_images.items():
        modules[module_id]["结果图"] = [str(path) for path in paths]

    for group in modules["02"].get("医生结果分组") or []:
        if "油光" in str(group.get("title")):
            _set_group_image(group, images["02_oil"], "表面油光分布")
        elif "荧光" in str(group.get("title")):
            _set_group_image(group, images["02_porphyrin"], "毛囊荧光分布")
    for group in modules["03"].get("医生结果分组") or []:
        title = str(group.get("title"))
        if "可见" in title:
            _set_group_image(group, images["03_visible"], "可见色斑结果")
        elif "UV" in title:
            _set_group_image(group, images["03_uv"], "UV色斑结果")
        elif "Brown" in title:
            _set_group_image(group, images["03_brown"], "Brown综合色素结果")
        else:
            _set_group_image(group, None, "")
    for group in modules["04"].get("医生结果分组") or []:
        _set_group_image(
            group,
            images["04"] if "强度" in str(group.get("title")) else None,
            "红区结果",
        )
    for module_id, key, caption in (
        ("05", "05", "血管样结构分布"),
        ("07", "07", "干燥性细纹分布"),
        ("11", "11", "面部轮廓几何测量"),
    ):
        for group in modules[module_id].get("医生结果分组") or []:
            _set_group_image(group, images[key], caption)
    for group in modules["10"].get("医生结果分组") or []:
        _set_group_image(
            group,
            images["10"] if "纹理" in str(group.get("title")) else None,
            "表面纹理分布",
        )


def _portable(payload: dict[str, Any], report_root: Path) -> dict[str, Any]:
    output = copy.deepcopy(payload)

    def convert(value: Any) -> None:
        if isinstance(value, dict):
            for key, child in value.items():
                if key in {"path", "结果图"}:
                    if isinstance(child, str) and Path(child).is_absolute():
                        value[key] = Path(child).relative_to(report_root).as_posix()
                    elif isinstance(child, list):
                        value[key] = [
                            Path(item).relative_to(report_root).as_posix()
                            if isinstance(item, str) and Path(item).is_absolute()
                            else item
                            for item in child
                        ]
                else:
                    convert(child)
        elif isinstance(value, list):
            for child in value:
                convert(child)

    convert(output)
    return output


def generate_clinic_dual_reports_from_twelve_result(
    result_dir: str | Path,
    *,
    subject_id: str | None = None,
    runtime_items: RuntimeItems,
) -> dict[str, str]:
    result_root = Path(result_dir).expanduser().resolve()
    index_path = result_root / "十二项检测结果索引.json"
    index = json.loads(index_path.read_text(encoding="utf-8"))
    if index.get("状态") != "success" or int(index.get("成功项目数", 0)) != 12:
        raise RuntimeError("正式双版只接受十二项全部成功的公开结果")

    baseline_root = _baseline_root()
    alias = _capture_alias(result_root, index, baseline_root)
    payload = json.loads(_baseline_json(baseline_root, alias).read_text(encoding="utf-8"))
    payload["受检者信息"]["姓名或编号"] = subject_id or alias
    refresh_report_dates(payload, date.today())
    vascular_metrics_path = Path(
        str(runtime_items["vascular"]["量化JSON"])
    ).resolve(strict=True)
    apply_vascular_metric_layout(
        payload,
        json.loads(vascular_metrics_path.read_text(encoding="utf-8-sig")),
    )
    report_root = result_root / "正式报告"
    report_root.mkdir(parents=True, exist_ok=True)
    source_input = _resolve_artifact(result_root, index["输入图像"])
    source = _stage(source_input, report_root, "00")
    images = _image_map(result_root, index, report_root)
    _bind_images(payload, images, source)
    with tempfile.TemporaryDirectory(
        prefix=".clinic-controlled-",
        dir=result_root,
    ) as temporary:
        controlled = materialize_controlled_evidence(
            source_image=source_input,
            runtime_items=runtime_items,
            candidate_sample_root=Path(temporary),
            capture_profile=CaptureProfile.INSTITUTION,
        )
        staged_controlled = ControlledEvidencePaths(
            red_brown_mixed=_stage(
                controlled.red_brown_mixed,
                report_root,
                "03",
            ),
            priority_pigment=_stage(
                controlled.priority_pigment,
                report_root,
                "03",
            ),
            surface_irregularity=_stage(
                controlled.surface_irregularity,
                report_root,
                "10",
            ),
        )
        bind_controlled_evidence(payload, staged_controlled)

        user = report_root / f"AISIA_{result_root.name}_用户精简版.docx"
        doctor = report_root / f"AISIA_{result_root.name}_医生详细版.docx"
        render_user_docx(payload, DEFAULT_TEMPLATE, user)
        render_doctor_docx(payload, DEFAULT_TEMPLATE, doctor)
    structured = report_root / f"AISIA_{result_root.name}_正式结构化数据.json"
    structured.write_text(
        json.dumps(_portable(payload, report_root), ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    user_target = result_root / user.name
    doctor_target = result_root / doctor.name
    if user_target.exists() or doctor_target.exists():
        raise FileExistsError("机构正式Word已存在，拒绝覆盖")
    os.replace(user, user_target)
    os.replace(doctor, doctor_target)
    index["正式报告"] = {
        "用户精简版": user_target.name,
        "医生详细版": doctor_target.name,
    }
    index_path.write_text(json.dumps(index, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return {
        "user_docx": str(user_target),
        "doctor_docx": str(doctor_target),
        "structured_json": str(structured),
    }


__all__ = ["generate_clinic_dual_reports_from_twelve_result"]
from __future__ import annotations

"""Map current detector truth into the approved controlled-report table layout."""

from dataclasses import dataclass
from typing import TypeAlias


JsonScalar: TypeAlias = str | int | float | bool | None
JsonValue: TypeAlias = JsonScalar | list["JsonValue"] | dict[str, "JsonValue"]
JsonObject: TypeAlias = dict[str, JsonValue]
VASCULAR_REGION_LABELS = {
    "forehead": "额部",
    "nose_alar_nasal_side": "鼻翼及鼻侧",
    "left_periocular": "画面左眼周",
    "right_periocular": "画面右眼周",
    "left_zygoma": "画面左颧部",
    "right_zygoma": "画面右颧部",
    "left_cheek": "画面左面颊",
    "right_cheek": "画面右面颊",
    "left_jaw": "画面左下颌",
    "right_jaw": "画面右下颌",
}


@dataclass(frozen=True, slots=True)
class ControlledMetricLayoutError(RuntimeError):
    label: str

    def __str__(self) -> str:
        return f"正式报告指标布局缺失: {self.label}"


def _dictionary(value: JsonValue | None) -> JsonObject:
    return value if isinstance(value, dict) else {}


def _nested(document: JsonObject, *keys: str) -> JsonValue:
    current: JsonValue = document
    for key in keys:
        current = _dictionary(current).get(key)
    return current


def _module(payload: JsonObject, module_id: str) -> JsonObject:
    modules = payload.get("检测模块")
    if not isinstance(modules, list):
        raise ControlledMetricLayoutError("检测模块")
    for value in modules:
        if isinstance(value, dict) and value.get("模块编号") == module_id:
            return value
    raise ControlledMetricLayoutError(module_id)


def _metric(
    name: str,
    value: JsonValue,
    unit: str,
    display_type: str,
) -> JsonObject:
    return {
        "name": name,
        "medical_name": name,
        "value": value,
        "unit": unit,
        "display_type": display_type,
        "availability": "available" if value not in (None, "不可评估") else "unavailable",
    }


def _metrics_by_name(module: JsonObject) -> dict[str, JsonObject]:
    values: dict[str, JsonObject] = {}
    collections: list[JsonValue] = [module.get("核心指标"), module.get("医生结果分组")]
    for collection in collections:
        if not isinstance(collection, list):
            continue
        for row in collection:
            if not isinstance(row, dict):
                continue
            candidates = row.get("metrics") if "metrics" in row else [row]
            if not isinstance(candidates, list):
                continue
            for candidate in candidates:
                if isinstance(candidate, dict) and isinstance(candidate.get("name"), str):
                    values[str(candidate["name"])] = dict(candidate)
    return values


def _first(metrics: dict[str, JsonObject], *names: str) -> JsonObject:
    for name in names:
        value = metrics.get(name)
        if value is not None:
            return dict(value)
    return _metric(names[0], None, "", "TEXT")


def _detector(complete: JsonObject, item_id: str) -> JsonObject:
    detectors = _dictionary(complete.get("detector_results"))
    return _dictionary(_dictionary(detectors.get(item_id)).get("metrics"))


def _apply_pigmentation(payload: JsonObject, complete: JsonObject) -> None:
    module = _module(payload, "03")
    metrics = _metrics_by_name(module)
    uv = _dictionary(_detector(complete, "uv_spots").get("uv_spots"))
    total = _dictionary(_nested(uv, "总体指标"))
    core = _dictionary(total.get("核心指标"))
    auxiliary = _dictionary(total.get("辅助指标"))
    uv_count = _nested(auxiliary, "数量与密度", "特征数量（个）")
    uv_area = _nested(core, "范围与负担", "特征面积占比")
    uv_p90 = _nested(core, "信号强度", "P90强度（0～1）")
    module["核心指标"] = [
        _first(metrics, "可见斑点数量"),
        _first(metrics, "棕色实例数量", "Brown综合色素目标数量"),
        _first(metrics, "可见色斑主要集中区域"),
        _metric("UV色斑目标数量", uv_count, "个", "COUNT"),
        _metric("UV色斑面积占比", uv_area, "%", "PERCENTAGE"),
        _metric("P90 UV响应", uv_p90, "0～1", "INTENSITY_ENGINEERING"),
    ]


def apply_vascular_metric_layout(
    payload: JsonObject,
    raw: JsonObject,
) -> None:
    module = _module(payload, "05")
