        _metric("面积占比", raw.get("vascular_area_ratio"), "%", "PERCENTAGE"),
        _metric("P90宽度", raw.get("p90_width_px"), "像素", "PIXEL"),
        _metric("P90红色强度", raw.get("p90_redness"), "工程响应", "INTENSITY_ENGINEERING"),
        _metric("分支点数量", raw.get("branch_point_count"), "个", "COUNT"),
        _metric("最大连续网络长度", raw.get("max_continuous_network_length_px"), "像素", "PIXEL"),
        _metric("白光可见支持率", raw.get("cp_rgb_visible_support_ratio"), "%", "PERCENTAGE"),
    ]
    module["核心指标"] = metrics
