        extra.write_bytes(str(index).encode())
        items["wrinkle"]["附加结果图"].append(extra.name)

    images = _formal_images(tmp_path, {"items": items})

    assert images["04"].name == "redness-marker.jpg"
    assert images["03_brown"].name == "brown-marker.jpg"


