        _metric("下颌曲率波动P90", raw.get("jaw_curve_p90"), "0～1", "ENGINEERING_0_1"),
        _metric("中面部曲面连续比例", raw.get("midface_surface_continuity_ratio"), "0～1", "ENGINEERING_0_1"),
    ]
    module["核心指标"] = metrics
    module["分区指标"] = []
    module["医生结果分组"] = [{
        "title": "面部轮廓几何测量",
        "summary": module.get("结果摘要", ""),
        "metrics": [dict(value) for value in metrics],
    }]


def apply_controlled_metric_layout(
    payload: JsonObject,
    complete: JsonObject,
) -> None:
